function randInt(rng,lo,hi){return lo+Math.floor(rng()*(hi-lo+1));}
function pick(rng,arr){return arr[Math.floor(rng()*arr.length)];}
function dice(rng,sides){return 1+Math.floor(rng()*(sides||6));}
function shuffle(a,rng){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(rng()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}return a;}
var EXPORTS={randInt:randInt,pick:pick,dice:dice,shuffle:shuffle};


